"""Demo: the pigeonhole equivalence SAT(m,k) <=> m <= k, cross-checked by brute force."""
from __future__ import annotations
from typing import Iterator, Tuple


def all_diff_sat(m: int, k: int) -> bool:
    """Predicted satisfiability of an AllDifferent block: m cells over k symbols."""
    return m <= k


def _all_assignments(m: int, k: int) -> Iterator[Tuple[int, ...]]:
    if m == 0:
        yield ()
        return
    for head in range(k):
        for tail in _all_assignments(m - 1, k):
            yield (head, *tail)


def brute_force_sat(m: int, k: int) -> bool:
    """Search every assignment for an injective one (exponential ground truth)."""
    if m == 0:
        return True
    return any(len(set(a)) == m for a in _all_assignments(m, k))


def main() -> None:
    for m in range(6):
        for k in range(6):
            assert all_diff_sat(m, k) == brute_force_sat(m, k)
            flag = "SAT" if all_diff_sat(m, k) else "UNSAT"
            print(f"m={m}, k={k}: {flag}")
    print("Pigeonhole prediction matches exhaustive search for all m,k < 6.")


if __name__ == "__main__":
    main()

"""Demo: the falling-factorial partition function Z(m,k) and its collapse at threshold."""
from __future__ import annotations
from math import factorial


def num_proper(m: int, k: int) -> int:
    """Falling factorial k^{underline m} = k(k-1)...(k-m+1); zero when m > k."""
    result = 1
    for i in range(m):
        result *= (k - i)
        if result <= 0:
            return 0
    return result


def main() -> None:
    for k in [4, 9]:
        print(f"alphabet k={k}:")
        for m in range(k + 3):
            z = num_proper(m, k)
            note = ""
            if m == k:
                note = f"  (= {k}! = {factorial(k)}, criticality)"
            if m == k + 1:
                note = "  (collapse to 0)"
            print(f"    Z({m:2d},{k}) = {z}{note}")
        assert num_proper(k, k) == factorial(k)
        assert num_proper(k + 1, k) == 0
    print("Partition function is positive iff m <= k and vanishes exactly beyond.")


if __name__ == "__main__":
    main()

"""Demo: order-n Sudoku lines sit exactly at criticality m = k = n^2, and the
cyclic Latin square solves rows/columns but fails boxes."""
from __future__ import annotations
from typing import List


def sudoku_line_size(n: int) -> int:
    """Cells per line (and symbols) of an order-n Sudoku: n^2."""
    return n * n


def cyclic_latin(side: int) -> List[List[int]]:
    """The side x side cyclic Latin square L(i,j) = (i+j) mod side."""
    return [[(i + j) % side for j in range(side)] for i in range(side)]


def is_latin_square(grid: List[List[int]]) -> bool:
    side = len(grid)
    full = set(range(side))
    rows = all(set(r) == full for r in grid)
    cols = all({grid[i][j] for i in range(side)} == full for j in range(side))
    return rows and cols


def boxes_ok(grid: List[List[int]], n: int) -> bool:
    side = n * n
    full = set(range(side))
    for br in range(0, side, n):
        for bc in range(0, side, n):
            box = {grid[br + di][bc + dj] for di in range(n) for dj in range(n)}
            if box != full:
                return False
    return True


def main() -> None:
    for n in [2, 3, 4]:
        s = sudoku_line_size(n)
        print(f"order n={n}: m = k = {s}  ->  critically satisfiable, "
              f"one cell from infeasibility")
    grid = cyclic_latin(9)  # order n=3
    print("cyclic Latin square (order 3):")
    for row in grid:
        print("   ", row)
    print(f"rows & columns all-different: {is_latin_square(grid)}")
    print(f"boxes all-different:          {boxes_ok(grid, 3)}  "
          "(boxes are genuinely independent constraints)")


if __name__ == "__main__":
    main()

