from __future__ import annotations
from typing import List, Optional


def decide_all_different(m: int, k: int) -> bool:
    """Decide satisfiability of an AllDifferent block in O(1) via pigeonhole."""
    return m <= k


def certificate(m: int, k: int) -> Optional[List[int]]:
    """Return an injective assignment [0..m) -> [0..k) if one exists, else None.

    Satisfiable case: the inclusion i |-> i is injective (O(m)).
    Unsatisfiable case: no injection exists (return None).
    """
    if m <= k:
        return list(range(m))
    return None

